def addable(cls, parent, set=None, raiseexceptions=True):
        """Checks whether a new element of the given type can be added to the parent.

        This method is mostly for internal use. It checks the ``OCCURRENCES`` attribute, which specifies the maximum number of occurrences allowed for this element. If the parent already has the maximum number of occurrences, and raiseexceptions is True, a DuplicateAnnotationError is raised. If raiseexceptions is False, the method returns False.

        Parameters:
            cls (type): The type of element to add
            parent (AbstractElement): The parent element
            set (str or None): The set
            raiseexceptions (bool): Raise an exception if the element can't be added?

        Returns:
            bool

        Raises:
            DuplicateAnnotationError
        """
        if cls.OCCURRENCES > 0:
            # Check if the parent doesn't have too many already
            count = parent.count(cls, None, True, [True, AbstractStructureElement])  # Never descend into embedded structure annotatio
            if count >= cls.OCCURRENCES:
                if raiseexceptions:
                    if parent.id:
                        extra = ' (id=' + parent.id + ')'
                    else:
                        extra = ''
                    raise DuplicateAnnotationError(f'Unable to add another object of type {cls.__name__} to {parent.__class__.__name__} {extra}. There are already {count} instances of this class, which is the maximum.')  # noqa: E501
                else:
                    return False

        if (cls.OCCURRENCES_PER_SET > 0) and set and (cls.REQUIRED_ATTRIBS is not None) and (Attrib.CLASS in cls.REQUIRED_ATTRIBS):
            count = parent.count(cls, set, True, [True, AbstractStructureElement])
            if count >= cls.OCCURRENCES_PER_SET:
                if raiseexceptions:
                    if parent.id:
                        extra = ' (id=' + parent.id + ')'
                    else:
                        extra = ''
                    raise DuplicateAnnotationError(f'Unable to add another object of set {set} and type {cls.__name__} to {parent.__class__.__name__} {extra}. There are already {count} instances of this class, which is the maximum for the set.')  # noqa: E501
                else:
                    return False

        return True

def unit_of_work(method):
    def _unit_of_work(self, tx, metadata=None, timeout=None):
        try:
            tx.timeout(timeout)
            return method(self, tx, metadata=metadata)
        except TransactionError as e:
            if e.code == "Neo.ClientError.Transaction.TransactionTimedOut":
                raise TimeoutError from e
            raise
    return _unit_of_work

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    values = []
    if not keys:
        values = list(self._record.values())
    else:
        for key in keys:
            if key in self._record:
                values.append(self._record[key])
    return values

