def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            try:
                return cache[k]
            except KeyError:
                pass # key not found in cache, need to call func
            except TypeError:
                # key not hashable, need to call func
                pass
            with lock:
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except KeyError:
                    # key not hashable, can't cache it
                    pass
            return v
        return wrapper
    return decorator

