    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise ValueError("Coord name must be a string.")
    if coord_name not in self.coords:
        raise IndexError(f"Invalid coord name: {coord_name}")
    error_indices = []
