def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # determine the specification version
    version = self.spec_version
    if extract_spec_version and 'type' in inventory:
        type_ = inventory['type']
        if type_ in self.SPEC_VERSIONS:
            version = self.SPEC_VERSIONS[type_]

    # check that all required attributes are present
    for attr in self.REQUIRED_ATTRIBS:
        if attr not in inventory:
            raise KeyError("Missing required attribute: %s" % attr)

    # check that there are no extra attributes
    for attr in inventory:
        if attr not in self.VALID_ATTRIBS:
            raise KeyError("Unexpected attribute: %s" % attr)

    # check that values are valid
    for attr in inventory:
        if attr not in self. VALID_ATTRIBS:
            raise ValueError("Invalid value for attribute: %s" % attr)

    # check that there are no duplicate occurrences of the same element
    if self.OCCURRENCES > 0:
        count = inventory.count(self)
        if count > self.OCCURRENCES:
            raise DuplicateAnnotationError("Unable to add another object of type %s. There are already %d instances of this class, which is the maximum." % (self.__class__.__name__, count))

    # check that there are no duplicate occurrences of the same element in the same set
    if self.OCCURRENCES_PER_SET > 0 and self.REQUIRED_ATTRIBS and Attrib.CLASS in self.REQUIRED_ATTRIBS:
        count = inventory.count(self, set, True, [True, AbstractStructureElement])
        if count > self.OCCURRENCES_PER_SET:
            raise DuplicateAnnotationError("Unable to add another object of set %s and type %s. There are already %d instances of this class, which is the maximum for the set." % (set, self.__class__.__name__, count))

    # validate attributes
    for attr in inventory:
        if attr in self.REQUIRED_ATTRIBS and not inventory[attr]:
            raise FieldError("Missing required value for attribute %s" % attr)
        if attr in self.VALID_ATTRIBS:
            if not self.VALID_ATTRIBS[attr](inventory[attr]):
                raise FieldError("Invalid value for attribute %s: %s" % (attr, inventory[attr]))

    # validate parent-child relationships
    for child in self:
        if not isinstance(child, AbstractElement):
            raise TypeError("Child element of type %s is not a subclass of AbstractElement" % child.__class__.__name__)
        child.validate(inventory, extract_spec_version)

    # validate document
    if self.doc and not isinstance(self.doc, Document):
        raise DocumentError("Parent element is not a Document object")

    # validate annotations
    for annot in self.annotations:
        if not isinstance(annot, Annotation):
            raise TypeError("Annotation of type %s is not a subclass of Annotation" % annot.__class__.__name__)

    # validate text content
    for text in self.text_contents:
        if not isinstance(text, TextContent):
            raise TypeError("Text content of type %s is not a subclass of TextContent" % text.__class__.__name__)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for file in manifest_files:
        if file.digest not in digests_used:
            raise ValueError(f"Digest {file.digest} from file {file} is not used.")
        if file.digest not in self.digests:
            raise ValueError(f"Digest {file.digest} from file {file} is not present in manifest.")

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("Input prior is not an InventoryValidator object")
        # Check that prior is an earlier version than current object
        if self.version == prior.version:
            raise ValueError("Input prior is the same version as current object")
        if self.version > prior.version:
            raise ValueError("Input prior is a later version than current object")
        # Check that prior's inventory contains all items and quantities in current inventory
        for item in self.items.values():
            if item not in prior.items:
                raise ValueError(f"Item {item.name} not found in prior inventory")
            elif prior.items[item] < item.quantity:
                raise ValueError(f"Insufficient quantity of item {item.name} in prior inventory")
        # Check that current inventory does not contain items not found in prior inventory
        for item in prior.items:
            if item not in self.items.keys():
                raise ValueError(f"Item {item.name} not found in current inventory")
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    try:
        if not isinstance(fixity, dict):
            raise ValueError('Invalid fixity block: not a dictionary')
        for key, value in fixity.items():
            if key not in manifest_files:
                raise ValueError("Invalid file reference in fixity block: '%s' is not in the manifest" % key)
            if not isinstance(value, str):
                raise ValueError("Invalid fixity value for file '%s': not a string" % key)
            if value not in ('md5', 'sha1'):
                raise ValueError("Invalid fixity value for file '%s': '%s' is not a valid algorithm" % (key, value))
    except Exception as e:
        raise ValidationError("Invalid fixity block in inventory:\n%s" % str(e)) from e

