def _extract_number_and_supplement_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    issue_text = issue.text.strip()

    number = None
    supplement = None

    # Extract number
    number_match = re.search(r'\d+', issue_text)
    if number_match:
        number = int(number_match.group(0))

    # Extract supplement
    supplement_match = re.search(r'Suppl\.* (\d+)', issue_text)
    if supplement_match:
        supplement = supplement_match.group(1)

    # Handle special cases
    if issue_text.endswith('spe') or issue_text.endswith('sup') or issue_text.endswith('supp'):
        supplement = 'spe'

    if issue_text.endswith('sup') or issue_text.endswith('supp') or issue_text.startswith('suppl'):
        supplement = 'supp'

    if number is not None and supplement is not None:
        return (number, supplement)
    elif number is not None:
        return (number, None)
    elif supplement is not None:
        return (None, supplement)
    else:
        raise ValueError("Could not extract number and supplement from issue element: '{0}'".format(issue_text))

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption:
        A & (A | B) = A, A | (A & B) = A

    Negative absorption:
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Expression):
            if arg.op == Operator.AND:
                if self.check_absorption(arg.op1, arg.op2):
                    new_args.append(arg.op1)
                else:
                    new_args.append(arg)
            elif arg.op == Operator.OR:
                if self.check_absorption(arg.op1, arg.op2):
                    new_args.append(arg.op2)
                else:
                    new_args.append(arg)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

