def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
      import json
      data = json.loads(document)
    except ValueError:
      from six import BytesIO
      from xmpp.utils.etree import tostring
      from xmpp.utils.webrss import RssParser
      rss_parser = RssParser(BytesIO(document))
      rss_tree = rss_parser.get_tree()
      data = rss_tree.getroot()

    aliases = []
    for item in data.findall(" XRD/Alias"):
      if item.text:
        aliases.append(item.text)

    profiles = []
    for item in data.findall(" XRD/Link"):
      if item.attrib["rel"] == "profile":
        profiles.append(item.attrib["href"])

    return {"aliases": aliases, "profiles": profiles}

