def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): The dictionary containing the parsed data from the spec file.

    Raises:
        ValueError: If the required attributes are not present in the dictionary.
        KeyError: If any of the required attributes are not found in the dictionary.
        TypeError: If the type of any of the attributes is not as expected.
    """
    try:
        include_file = parser_dict['include']
    except KeyError:
        raise ValueError("The 'include' attribute is required in the parser dict.") from None
    except TypeError:
        raise TypeError("The 'include' attribute must be a string.") from None
    if not isinstance(include_file, str) or not include_file:
        raise ValueError("The 'include' attribute must be a non-empty string.")

    try:
        include_groups = parser_dict['groups']
    except KeyError:
        raise ValueError("The 'groups' attribute is required in the parser dict.") from None
    except TypeError:
        raise TypeError("The 'groups' attribute must be a list.") from None
    if not isinstance(include_groups, list) or not include_groups:
        raise ValueError("The 'groups' attribute must be a non-empty list.")

    try:
        included_names = parser_dict['names']
    except KeyError:
        raise ValueError("The 'names' attribute is required in the parser dict.") from None
    except TypeError:
        raise TypeError("The 'names' attribute must be a list.") from None
    if not isinstance(included_names, list) or not included_names:
        raise ValueError("The 'names' attribute must be a non-empty list.")

    # Check if the include file exists
    filepath = os.path.join(os.path.dirname(__file__), include_file)
    if not os.path.exists(filepath):
        raise FileNotFoundError(f"The file '{include_file}' does not exist.")

    # Read the include file
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()
        groups_dict = {}
        cur_group = None
        for line in lines:
            line = line.strip()
            # Skip empty lines and comments
            if not line or line.startswith('#'):
                continue
            # Check if we have a new group
            if line.startswith('['):
                cur_group = line[1:-1].strip()
                if cur_group not in include_groups:
                    raise ValueError(f"The specified group '{cur_group}' is not valid.")
                groups_dict[cur_group] = []
            # Add the line to the current group
            else:
                if cur_group is None:
                    raise ValueError("A value is specified outside of a group.")
                groups_dict[cur_group].append(line)

    # Filter the groups based on the names provided
    filtered_groups = {}
    for group, lines in groups_dict.items():
        if len(lines) == 1:
            filtered_groups[group] = lines[0]
    if len(filtered_groups) == 0:
        raise ValueError("No group was specified in the include file.")

    # Remove the include and groups attributes
    parser_dict.pop('include')
    parser_dict.pop('groups')

    # Add the filtered groups to the dictionary
    parser_dict.update(filtered_groups)

    return parser_dict

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name.

    Args:
        command_name (str): The name of the command.
        argument_name (str): The name of the argument for which to get the option specification.

    Returns:
        OptionSpec: The option specification for the specified argument, or None if not found.
    """
    argument = Argument(argument_name)
    if argument.option_name:
        options = self.get_command_options(command_name)
        if options:
            for option in options:
                if option.name == argument.option_name:
                    return option
    return None

def validate_requires_args(self, args):
        """Check if all the required arguments have been provided. """
        if not args:
            return False
        for key in self.REQUIRED_ARGS:
            if key not in args:
                return False
        return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    conditionally_required_args = []
    for option in options_spec:
        if option['required_when'] is not None:
            condition_met = False
            for when in option['required_when']:
                if when['command'] == command_name and when['options'] <= args:
                    condition_met = True
                    break
            if condition_met:
                conditionally_required_args.append(option['name'])
    return conditionally_required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for key, value in args.items():
        if key in self.args_length_validation:
            max_length = self.args_length_validation[key]
            if len(value) > max_length:
                raise ValueError(f"The value of argument '{key}' is longer than the maximum allowed length ({max_length}).")

def validate_choices_args(self, args):
    for arg in args:
        if not self.available_choices or arg not in self.available_choices:
            raise ValueError("The value of the argument is not one of the available choices.")

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        for key, value in args.items():
            if not isinstance(value, int):
                raise ValueError(f"Invalid argument: {key} must be an integer.")
            if value < self.min or value > self.max:
                raise ValueError(f"Invalid argument: {key} must be between {self.min} and {self.max}.")

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg == "control":
            control_args["control"] = args["control"]
        elif arg == "nested":
            nested_args["nested"] = args["nested"]
        elif arg == "custom":
            custom_args["custom"] = args["custom"]
        else:
            raise ValueError("Invalid argument")

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    for var in extra_vars:
        if var in vars_dict:
            vars_dict[var] = vars_dict[var] + extra_vars[var]
        else:
            vars_dict[var] = extra_vars[var]
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        #perform the actual argument conversion here
        for arg_name in values_dict:
            arg_value = values_dict[arg_name]
            if arg_value.isdigit():
                values_dict[arg_name] = int(arg_value)
            elif arg_value.lower() in ["true", "false"]:
                values_dict[arg_name] = arg_value.lower() == "true"
            #else:
                #keep default string value
    elif parser_name == "virsh":
        #perform the actual argument conversion here
        for arg_name in values_dict:
            arg_value = values_dict[arg_name]
            if arg_value.isdigit():
                values_dict[arg_name] = int(arg_value)
            elif arg_value.lower() in ["on", "off"]:
                values_dict[arg_name] = arg_value.lower() == "on"
            #else:
                #keep default string value
    elif parser_name == "ospd":
        #perform the actual argument conversion here
        for arg_name in values_dict:
            arg_value = values_dict[arg_name]
            if arg_value.isdigit():
                values_dict[arg_name] = int(arg_value)
            elif arg_value.lower() in ["yes", "no"]:
